// TwentyOne: recover the 0.1.3 emit-all failure using individual entry points.
// Keep the normal asset import/GUID handling in Compile after this returns.
if (entryClass == null && process.ExitCode == 1 && stderr.Contains("program(s) failed"))
{
    bool succeeded = true;
    int count = 0;
    foreach (string source in sources)
    {
        MonoScript script = AssetDatabase.LoadAssetAtPath<MonoScript>(source.Replace('\\', '/'));
        Type entry = script != null ? script.GetClass() : null;
        if (entry == null || entry.IsAbstract || entry.ContainsGenericParameters
            || !typeof(MenSharp.MenSharpBehaviour).IsAssignableFrom(entry)) continue;
        count++;
        if (!RunCompiler(binary, outputDirectory, sources, foreign, entry.FullName))
        {
            succeeded = false;
            continue;
        }
        // Single-entry emission omits source; preserve the asset's original folder/GUID.
        string metaPath = Path.Combine(outputDirectory, entry.FullName + ".meta.json");
        string metadata = File.ReadAllText(metaPath);
        metadata = metadata.Insert(metadata.IndexOf('{') + 1,
            "\n  \"source\": \"" + source.Replace('\\', '/') + "\",");
        File.WriteAllText(metaPath, metadata, new UTF8Encoding(false));
    }
    if (count == 0) succeeded = false;
    if (succeeded) Debug.Log($"MenSharp: emit-all fallback compiled {count} individual programs.");
    return succeeded;
}
